fs = 1000;
t = (0:fs-1)'/fs;
x = sin(2*pi*100*t) + sin(2*pi*200*t);
fprintf('%.1f\n', meanfreq(x, fs));
fprintf('%.1f\n', meanfreq(x, fs, [50 150]));

fs = 1000;
t = (0:fs-1)'/fs;
x = sin(2*pi*100*t) + sin(2*pi*200*t);
fprintf('%.1f\n', medfreq(x, fs));
[p, f] = periodogram(x, [], [], fs);
fprintf('%.1f\n', medfreq(p, f, [150 300]));

n = (0:99)';
x = sin(2*pi*n/20);
fprintf('%.4f\n', peak2rms(x));
y = [zeros(99,1); 10];
fprintf('%.4f\n', peak2rms(y));

[p, num] = seqperiod([2 5 7 2 5 7 2 5 7 2 5 7]);
fprintf('%d %d\n', p, num);
p = seqperiod([1 2 3 1 2.01 3 1 2 3.01], 0.05);
fprintf('%d\n', p);

a = [0 0 1 3 5 3 1 0 0 0 0 0];
b = [0 0 0 0 0 1 3 5 3 1 0 0];
[xa, ya, d] = alignsignals(a, b);
fprintf('delay %d\n', d);
disp(xa)
disp(ya)

x = [0.1*sin(1:40)'; 3 + 0.1*sin(1:20)'];
[iup, ilo] = cusum(x);
disp(iup)
disp(isempty(ilo))

x = [1 2 3 4 3 2 1];
y = [1 3 4 4 3 2 1 1];
[d, ix, iy] = dtw(x, y);
fprintf('%g\n', d);
disp(ix')
disp(iy')
fprintf('%g\n', dtw(x, y, 'squared'));

x = [zeros(1,8) 2*ones(1,8) + 0.1*(-1).^(1:8)];
disp(findchangepts(x, 'Statistic', 'mean'))
y = [0.1*sin(1:30) 2*sin(1:30)];
disp(findchangepts(y, 'Statistic', 'std', 'MaxNumChanges', 1))

a = [0 0 1 3 5 3 1 0 0 0 0 0];
b = [0 0 0 0 0 1 3 5 3 1 0 0];
fprintf('%d\n', finddelay(a, b));
fprintf('%d\n', finddelay(b, a));

y = [0 2 0 1 0 5 1 4 0 3 0];
[pks, locs] = findpeaks(y);
disp(pks)
disp(locs)
[pks, locs] = findpeaks(y, 'MinPeakHeight', 2.5);
disp(pks)
disp(locs)

y = [0 2 0 1 0 5 1 4 0 3 0];
[pks, locs, w, p] = findpeaks(y, 'MinPeakProminence', 1.5);
disp(locs)
disp(w)
disp(p)

d = [zeros(1,5) 1 2 3 2 1 zeros(1,5) 1.1 2.1 3 2 1 zeros(1,4)];
[s, e, dist] = findsignal(d, [1 2 3 2 1], 'MaxNumSegments', 2, 'Normalization', 'none');
disp(s)
disp(e)
disp(round(dist * 1000) / 1000)

n = (0:99)';
x = sin(2*pi*n/20 + 0.3);
[r, c] = zerocrossrate(x, 'Method', 'comparison');
fprintf('%.2f %d\n', r, c);
r = zerocrossrate(x, 'WindowLength', 50);
fprintf('%.2f\n', r);

x = [zeros(1,5) ones(1,4) zeros(1,3) ones(1,4) zeros(1,3)];
d = dutycycle(x);
fprintf('%.4f\n', d);

t = (0:0.01:1)';
y = 1 - exp(-8*t);
y = 1 - y;
fprintf('%.4f\n', falltime(y, t));

t = (0:0.01:1)';
y = 1 - exp(-8*t);
fprintf('%.4f\n', midcross(y, t));
fprintf('%.4f\n', midcross(y, t, 'MidPercentReferenceLevel', 25));

x = [zeros(1,5) ones(1,4) zeros(1,3) ones(1,4) zeros(1,3)];
[p, i1, f1, n1] = pulseperiod(x);
disp(p)
disp([i1 f1 n1])

x = [zeros(1,5) ones(1,4) zeros(1,3) ones(1,4) zeros(1,3)];
s = pulsesep(x);
disp(s)
s = pulsesep(x, 100);
disp(s)

x = [zeros(1,5) ones(1,4) zeros(1,3) ones(1,4) zeros(1,3)];
w = pulsewidth(x);
disp(w)
w = pulsewidth(x, 100);
disp(w)

t = (0:0.01:1)';
y = 1 - exp(-8*t);
[r, lt, ut] = risetime(y, t);
fprintf('%.4f %.4f %.4f\n', r, lt, ut);

z = [0 0 0 0 0 0.2 0.6 1.3 1.1 0.9 1.05 0.98 1.01 1 1 1 1 1 1 1];
[s, lev, inst] = settlingtime(z, 5);
fprintf('%.3f %.3f %.3f\n', s, lev, inst);
[s, lev, inst] = settlingtime(z, 3);
disp(s)

t = (0:0.01:1)';
y = 1 - exp(-8*t);
[s, lt, ut] = slewrate(y, t);
fprintf('%.4f %.4f %.4f\n', s, lt, ut);

